#include<iostream>
#include<vector>
#include<map>
#include<set>
using namespace std;
typedef long long ll;
const int N = 2e5 + 10;
int t, n, k, a[N], ans;
set<int> d[N];
map<int, map<ll, vector<int> > > mp;

int main(){
	cin >> t;
	while(t--){
		cin >> n >> k; mp.clear(); ans = 0;
		for(int i = 1; i <= n; i++){
			cin >> a[i]; d[i].clear();
		}
		for(int i = 1; i <= n; i++){
			for(int j = i+1; j <= min(n, i+k+1); j++){
				if((a[j]-a[i])%(j-i) == 0){
					d[i].insert((a[j]-a[i])/(j-i));
					d[j].insert((a[j]-a[i])/(j-i));
				}
			}
		}
		for(int i = 1; i <= n; i++){
			for(int j: d[i]){
				mp[j][a[i]-(ll)j*i].push_back(i);
			}
			d[i].clear();
		}
		for(const auto &i: mp){
			for(const auto &j: i.second){
				for(int l = 0, r = 0; r < j.second.size(); r++){
					if((j.second[r]-j.second[l]+1) - (r-l+1) > k) l++;
					ans = max(ans, min(n, r-l+1+k));
				}
			}
		}
		cout << ans << '\n';
	}
	return 0;
}
