using namespace std;
typedef long long ll;
const int N = 2e5 + 10;
int t, n, k, a[N], ans;
vector<int> d[N];
map<int, map<ll, vector<int> > > mp;

int main(){
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> t;
    while(t--){
        cin >> n >> k; mp.clear(); ans = 0;
        for(int i = 1; i <= n; i++){
            cin >> a[i]; d[i].clear();
        }
        for(int i = 1; i <= n; i++){
            for(int j = i+1; j <= min(n, i+k+1); j++){
                if((a[j]-a[i])%(j-i) == 0){
                    d[i].push_back((a[j]-a[i])/(j-i));
                    d[j].push_back((a[j]-a[i])/(j-i));
                }
            }
            sort(d[i].begin(), d[i].end());
            d[i].erase(unique(d[i].begin(), d[i].end()), d[i].end());
            for(int j: d[i]){
                auto &v = mp[j][a[i]-(ll)j*i];
                if(v.empty()) v.reserve(2);
                v.push_back(i);
            }
            vector<int>().swap(d[i]);
        }
        for(const auto &i: mp){
            for(const auto &j: i.second){
                for(int l = 0, r = 0; r < j.second.size(); r++){
                    if((j.second[r]-j.second[l]+1) - (r-l+1) > k) l++;
                    ans = max(ans, min(n, r-l+1+k));
                }
            }
        }
        cout << ans << '\n';
    }
    return 0;
}

