这次 [RE](https://codeforces.com/contest/2285/submission/399205690) 是 **`mp[j]` 越界**：

```cpp
map<ll, vector<int> > mp[N];
```

这里的 `j` 是**公差的离散化编号**，不同公差的数量并不受 \(n\) 限制，最多为 \(O(nk)\)。

例如合法数据：

- \(n=1000,\ k=500\)
- \(a_i=i^3\)

实际会得到 **282395 个不同公差**，超过 `N=200010`。

最小修改是将 `mp` 改为动态数组，在公差去重后执行 `mp.resize(ad.size())`。另外补上 `id.clear()`，防止多测累积旧键；它本身不会直接导致 WA。

```cpp
#include<iostream>
#include<vector>
#include<map>
#include<algorithm>

using namespace std;
typedef long long ll;

const int N = 2e5 + 10;
int t, n, k, a[N], ans;
vector<int> d[N], ad;
map<int, int> id;
vector<map<ll, vector<int> > > mp;

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> t;
	while(t--){
		cin >> n >> k; ad.clear(); id.clear(); ans = 0;
		for(int i = 1; i <= n; i++){
			cin >> a[i];
		}
		for(int i = 1; i <= n; i++){
			for(int j = i+1; j <= min(n, i+k+1); j++){
				if((a[j]-a[i])%(j-i) == 0) ad.push_back((a[j]-a[i])/(j-i));
			}
		}
		sort(ad.begin(), ad.end());
		ad.erase(unique(ad.begin(), ad.end()), ad.end());
		mp.resize(ad.size());
		for(int i = 0; i < ad.size(); i++){
			id[ad[i]] = i;
		}
		for(int i = 1; i <= n; i++){
			for(int j = i+1; j <= min(n, i+k+1); j++){
				if((a[j]-a[i])%(j-i) == 0){
					d[i].push_back(id[(a[j]-a[i])/(j-i)]);
					d[j].push_back(id[(a[j]-a[i])/(j-i)]);
				}
			}
			sort(d[i].begin(), d[i].end());
			d[i].erase(unique(d[i].begin(), d[i].end()), d[i].end());
			for(int j: d[i]){
				auto &v = mp[j][a[i]-(ll)ad[j]*i];
				if(v.empty()) v.reserve(2);
				v.push_back(i);
			}
			vector<int>().swap(d[i]);
		}
		for(int i = 0; i < ad.size(); i++){
			for(const auto & j: mp[i]){
				for(int l = 0, r = 0; r < j.second.size(); r++){
					if((j.second[r]-j.second[l]+1) - (r-l+1) > k) l++;
					ans = max(ans, min(n, r-l+1+k));
				}
			}
			mp[i].clear();
		}
		cout << ans << '\n';
	}
	return 0;
}
```

