using namespace std;
typedef long long ll;

const int N = 2e5 + 10;
int t, n, k, a[N], ans;
vector<int> d[N], ad;
vector<vector<pair<ll, int> > > mp;

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> t;
	while(t--){
		cin >> n >> k; ad.clear(); mp.clear(); ans = 0;
		for(int i = 1; i <= n; i++){
			cin >> a[i];
		}
		for(int i = 1; i <= n; i++){
			for(int j = i+1; j <= min(n, i+k+1); j++){
				if((a[j]-a[i])%(j-i) == 0) ad.push_back((a[j]-a[i])/(j-i));
			}
		}
		sort(ad.begin(), ad.end());
		ad.erase(unique(ad.begin(), ad.end()), ad.end());
		mp.resize(ad.size());
		for(int i = 1; i <= n; i++){
			for(int j = i+1; j <= min(n, i+k+1); j++){
				int x = a[j]-a[i], y = j-i;
				if(x%y == 0){
					int p = lower_bound(ad.begin(), ad.end(), x/y)-ad.begin();
					d[i].push_back(p);
					d[j].push_back(p);
				}
