主要优化两处：

1. **去掉 `ls`**：直接排序 `mp[i]`，相同截距连续，同组下标递增，可以直接双指针。
2. **去掉 `id`**：在有序的 `ad` 上二分，每对位置只查一次，减少红黑树访问。

同一组 `n=30000, k=333, a[i]=i²` 压力数据，本地 32 位 `-O2` 下，**3.74 秒 → 1.30 秒**，峰值约 **513 MiB**。16352 组小规模穷举及三组大数据检查通过，未线上提交。

```cpp
#include<iostream>
#include<vector>
#include<algorithm>

using namespace std;
typedef long long ll;

const int N = 2e5 + 10;
int t, n, k, a[N], ans;
vector<int> d[N], ad;
vector<vector<pair<ll, int> > > mp;

int main(){
	ios::sync_with_stdio(0);
	cin.tie(0); cout.tie(0);
	cin >> t;
	while(t--){
		cin >> n >> k; ad.clear(); mp.clear(); ans = 0;
		for(int i = 1; i <= n; i++){
			cin >> a[i];
		}
		for(int i = 1; i <= n; i++){
			for(int j = i+1; j <= min(n, i+k+1); j++){
				if((a[j]-a[i])%(j-i) == 0) ad.push_back((a[j]-a[i])/(j-i));
			}
		}
		sort(ad.begin(), ad.end());
		ad.erase(unique(ad.begin(), ad.end()), ad.end());
		mp.resize(ad.size());
		for(int i = 1; i <= n; i++){
			for(int j = i+1; j <= min(n, i+k+1); j++){
				int x = a[j]-a[i], y = j-i;
				if(x%y == 0){
					int p = lower_bound(ad.begin(), ad.end(), x/y)-ad.begin();
					d[i].push_back(p);
					d[j].push_back(p);
				}
			}
			sort(d[i].begin(), d[i].end());
			d[i].erase(unique(d[i].begin(), d[i].end()), d[i].end());
			for(int j: d[i]){
				mp[j].push_back({a[i]-(ll)ad[j]*i, i});
			}
			vector<int>().swap(d[i]);
		}
		for(auto &v: mp){
			sort(v.begin(), v.end());
			for(int l = 0, r = 0; r < v.size(); r++){
				if(r == 0 || v[r].first != v[r-1].first) l = r;
				if((v[r].second-v[l].second+1) - (r-l+1) > k) l++;
				ans = max(ans, min(n, r-l+1+k));
			}
		}
		cout << ans << '\n';
	}
	return 0;
}
```

